  'settings.reconnect.checkUrlHint': 'Dohvaća se prije izvođenja načina i još jednom poslije; izvođenje se smatra gotovim čim se adresa koju ispisuje promijeni. Zadane vrijednosti nema: upravitelj preuzimanja koji sam hostiraš ne bi trebao počinjati javljati tvoju adresu usluzi koju nikad nisi odabrao. Ono što ispisuje mora biti adresa koju vidi internet, jer stranica koja vraća adresu iz tvoje vlastite mreže ne može razlikovati ponovno spajanje od izvođenja koje ništa nije promijenilo.',
