  'props.name': 'Naziv',
  'props.nameHint': 'Jedan naziv datoteke, nikad putanja: sve što ispisuje mape skraćuje se na jedan naziv. Dovršeno preuzimanje preimenuje se i na disku, da si popis i mapa ne mogu proturječiti. Ono koje teče zadržava datoteku koju njegov backend drži otvorenom i novi naziv preuzima kad završi. Ono koje nije počelo preuzima ga odmah. Naziv pripada jednoj datoteci, pa se ovo polje nudi samo za jedan redak.',
  'props.comment': 'Napomena',
  'props.commentHint': 'Tvoja vlastita bilješka uz ovu poveznicu. Sprema se i prikazuje u popisu; ništa u aplikaciji se ne ravna po njoj.',
