  'props.autoExtract': 'Raspakiraj arhive',
  'props.autoExtractHint': 'Hoće li se arhiva raspakirati kad preuzimanje završi. „Naslijedi“ prepušta odluku stranici s postavkama arhiva, a to nije isto što i isključeno. Prekidač se čita u trenutku raspakiravanja, pa ako ga sad uključiš, raspakirat će se i nešto što je završilo ranije.',
