  'settings.scripts.triggerHint':
    'Što pokreće ovu skriptu. Uz Ručno se izvodi samo kad to zatražiš: putem „Testno pokretanje” ispod ili stavke „Pokreni skriptu” u izborniku desnog klika na popisu preuzimanja.',
