  'settings.access.relay.title': 'Relej projekta',
  'settings.access.relay.body': 'Relej je posrednik koji sve tvoje instance čini dostupnima izvan kućne mreže, dakle odasvud. Ovaj projekt nudi besplatno.',
  'settings.access.relay.use': 'Koristi relej projekta',
  'settings.access.relay.leadProject': 'Radi bez postavljanja. Sve što tvoje instance jedna drugoj kažu je šifrirano, a ključ imaš samo ti.',
  'settings.access.relay.seesButton': 'Što vidi?',
  'settings.access.relay.seesTip': 'Relayu nije vidljivo: tvoje poveznice, preuzimanja, datoteke i pristupni token.\n\nRelayu je vidljivo: IP adrese tvojih instanci i kada nešto pošalju.\n\nTo se ne da šifriranjem ukloniti. Ako ti smeta, pokreni vlastiti relay.',
  'settings.access.relay.seesAddress': 'Relej projekta radi na {address}.',
  'settings.access.relay.none': 'Bez releja',
  'settings.access.relay.noneHint': 'Nijedan relej nije aktivan. U istoj mreži, dakle kod kuće, instance se i dalje same nalaze. Preko različitih mreža ne dopiru jedna do druge, pa udaljenog pristupa nema.',
  'settings.access.relay.own': 'Vlastiti relej',
  'settings.access.relay.project': 'Relej projekta',
  'settings.access.relay.whichHint': 'Ide preko {address}',
  'settings.access.relay.savedProject': 'Relej projekta je aktivan',
  'settings.access.relay.savedOwn': 'Tvoj relej je aktivan',
  'settings.access.relay.savedOff': 'Relej isključen',
  'settings.access.ownRelay.title': 'Vlastiti relej',
  'settings.access.ownRelay.body': 'Pokreni vlastiti relej umjesto onog od projekta.',
  'settings.access.ownRelay.use': 'Koristi moj relej',
  'settings.access.ownRelay.lead': 'Dva puta: ova instanca preuzima relej, ili upišeš adresu.',
  'settings.access.ownRelay.serveLabel': 'Koristi ovu instancu kao relej',
  'settings.access.ownRelay.serveHint': 'Radi samo ako je ova instanca dostupna izvana, primjerice preko Nginx Proxy Managera i vlastite domene.',
  'settings.access.ownRelay.serveClients': 'Trenutno povezanih: {count}.',
  'settings.access.ownRelay.addressLabel': 'Adresa',
  'settings.access.ownRelay.addressPlaceholder': 'npr. https://relay.mojadomena.hr',
  'settings.access.ownRelay.save': 'Spremi',
  'settings.access.ownRelay.everyInstance': 'Ova adresa vrijedi samo za ovu instancu. Upiši je na svakoj.',
  'settings.access.ownRelay.containerLabel': 'Kao vlastiti kontejner',
  'settings.access.ownRelay.containerHint': 'Ako nijedna tvoja instanca nije dostupna izvana, relej mora biti negdje drugdje, na tvom poslužitelju ili malom VPS-u. Instaliraj kontejner iz Unraid Community Applications ili naredbom ispod.\n\nKontejneru ne treba postavljanje: pokreni ga, upiši njegovu adresu iznad, gotovo. Ništa ne sprema, pa nema ni što sigurnosno kopirati.',
  'settings.access.tokens.title': 'API tokeni',
  'settings.access.tokens.intro':
    'Imenovane vjerodajnice za skriptu, proširenje preglednika ili telefon. Svaku je moguće opozvati zasebno, bez promjene zajedničke lozinke koju koriste svi ostali klijenti.',
  'settings.access.tokens.empty': 'Još nije izdan nijedan token.',
  'settings.access.tokens.new': 'Novi token',
  'settings.access.tokens.namePlaceholder': 'npr. moj telefon',
