  'settings.access.tokens.secretTitle': 'Sada kopiraj ovaj token',
  'settings.access.tokens.secretWarning':
    'Ovaj token prikazan je samo ovaj jedan put. Pohranjen je na ovoj instanci kao jednosmjerni hash - ako se izgubi, nema načina da ga se ponovno pročita, samo da se opozove i stvori novi.',
  'settings.access.tokens.copy': 'Kopiraj',
