  'settings.access.identity.title': 'Identitet ove instance',
  'settings.access.identity.nameLabel': 'Naziv',
  'settings.access.identity.namePlaceholder': 'npr. Kućni poslužitelj',
  'settings.access.identity.nameHint': 'Nudi se prvo pri uparivanju i u QR kodu ispod, umjesto naziva koji operacijski sustav ili izvršno okruženje kontejnera slučajno daje ovom računalu. Neobavezno: ostavi prazno ako želiš i dalje koristiti taj naziv.',
  'settings.access.identity.domainsLabel': 'Poznate domene',
  'settings.access.identity.domainsHint': 'Svaka se domena automatski zapamti kad preko nje stigne prvi zahtjev i ostaje ovdje navedena i kad kasniji zahtjevi stižu preko LAN IP adrese. Domenu dodaj ručno ako je već postavljena, a preko nje još nije stigao nijedan zahtjev. Jedna potpuna adresa po retku, npr. https://kl.example.com.',
  'settings.access.cardTitle': 'Povezivanje instanci i udaljeni pristup',
  'settings.access.phrase.body': 'Jedna fraza povezuje sve KnightLoadere koje pokrećeš. Izradi je ovdje, a zatim je zalijepi u druge instance. Ne trebaš ni račun ni prijavu, a nema ništa za podešavanje.',
  'settings.access.phrase.noPasswordWarning': 'Ova instanca nema lozinku. Fraza otvara svaku instancu koju s njom povežete, pa tko je ovdje može pročitati dolazi do svih, ne samo do ove. Bolje prvo postavite lozinku iznad.',
  'settings.access.phrase.activate': 'Izradi frazu',
  'settings.access.phrase.howStep1': 'Na ovoj instanci pritisni „{button}“. Pojavit će se dvanaest riječi.',
  'settings.access.phrase.howStep2': 'Otvori KnightLoader na drugom uređaju, dođi na ovu istu stranicu, pritisni „{button}“ i upiši dvanaest riječi.',
  'settings.access.phrase.howStep3': 'Gotovo! Svaka instanca sada se pojavljuje kod druge pod „Instance“ i možeš upravljati bilo kojom s bilo koje. S uključenim relayem tvoje su instance dostupne i izvan tvoje mreže.',
  'settings.access.phrase.howWhat': 'Riječi su tajna, a ne adresa. Svaka instanca iz njih izračuna dva ključa: jedan za pronalaženje drugih, jedan za šifriranje.\n\nDa bi se našle, svaka instanca sama zove isto mjesto susreta na internetu. Tko pokaže isti ključ, biva spojen. Zato nijedna tvoja instanca ne mora biti dostupna izvana.\n\nMjesto susreta ne može čitati. Tvoje riječi nikad ne vidi, a sve što kroz njega prolazi šifrirano je drugim ključem.',
  'settings.access.phrase.statusDisconnected': 'Nije povezano',
  'settings.access.phrase.statusHintProject': 'Povezano s relejem projekta. Udaljeni pristup je postavljen.',
  'settings.access.phrase.statusHintOwn': 'Povezano s vlastitim relejem. Udaljeni pristup je postavljen.',
  'settings.access.phrase.statusHintOff': 'Nijedan relej nije aktivan. Tvoje su instance dostupne samo u lokalnoj mreži.',
  'settings.access.phrase.statusHintLost': 'Nema veze s relejem. KnightLoader i dalje pokušava. Do tada se instance nalaze samo u lokalnoj mreži.',
  'settings.access.phrase.statusConnected': 'Povezano',
