  'settings.nav.resolvers': 'Rješavači',
  'settings.module.ytdlp': 'yt-dlp',
  'settings.resolvers.moduleUnavailable': 'Modul nije dostupan',
  'settings.resolvers.moduleUnavailableHint': 'Sve ispod svejedno se sprema i stupa na snagu čim yt-dlp postane dostupan. Ništa što sad promijeniš neće se izgubiti.',
  'settings.resolvers.about': 'Postavke pozadine yt-dlp, koja dohvaća sadržaj sa stranica za medije i streaming koje podržava sam yt-dlp. Koja će usluga uopće obraditi neku poveznicu (yt-dlp, debrid račun ili pozadina JDownloader), odlučuje redoslijed prioriteta na stranici Računi. Ova stranica određuje što yt-dlp radi kad mu je poveznica usmjerena.',
  'settings.resolvers.quality': 'Kvaliteta',
  'settings.resolvers.videoFormat': 'Format videa',
  'settings.resolvers.qualityHint': 'Koji se selektor -f koristi pri pokretanju yt-dlp. Najbolja dostupna je vlastita zadana vrijednost yt-dlp-a, i ono što je svako preuzimanje koristilo prije nego što je ova postavka postojala.',
