  'settings.torrents.seedRatioHint': 'Nastavlja seedati dovršeni torrent dok se u roj ne vrati ovaj udio, u odnosu na njegovu vlastitu veličinu. 0 = bez cilja omjera.',
  'settings.torrents.seedDuration': 'Ciljno trajanje seedanja',
  'settings.torrents.seedDurationHint': 'Nastavlja seedati dovršeni torrent ovoliko dugo nakon dovršetka. 0 = bez vremenskog ograničenja. Seedanje se zaustavlja kad se prvi od gornja dva cilja postigne.',
  'settings.torrents.seedDurationUnit': 'sati',
  'settings.torrents.transferTitle': 'Ograničenje prijenosa',
  'settings.torrents.uploadLimit': 'Ograničenje slanja',
  'settings.torrents.uploadLimitHint': 'Ograničava koliko brzo torrent šalje podatke roju tijekom seedanja. 0 = bez ograničenja.',
  'settings.torrents.portTitle': 'Port i mapiranje',
  'settings.torrents.port': 'Port',
  'settings.torrents.portHint': 'Port na kojem ova instanca sluša veze roja. 0 prepušta odabir torrent mehanizmu.',
  'settings.torrents.portRestartHint': 'Mehanizam svoj torrent klijent izgrađuje samo jednom, pa novi port vrijedi tek nakon ponovnog pokretanja ove instance. Zamoliti usmjerivač za mapiranje može se odmah, bez obzira na to sluša li već neki torrent na njemu.',
  'settings.torrents.portMapHint': 'Traži od usmjerivača da putem UPnP-a proslijedi gornji port na ovo računalo, kako bi ga peerovi iza drugog usmjerivača ipak mogli dosegnuti. Ne podržavaju svi usmjerivači ovo, a neki prihvate zahtjev iako to zapravo ne radi.',
  'settings.torrents.portMapButton': 'Pokušaj UPnP mapiranja',
  'settings.torrents.portMapping': 'Pitanje usmjerivača…',
  'settings.torrents.portMapNeedsPort': 'Postavi port gore prije mapiranja. S 0 usmjerivač nema kamo proslijediti.',
  'settings.torrents.portMapConfirmed': 'Potvrđeno: port {port} je mapiran i provjereno je da je dostupan.',
  'settings.torrents.portMapUnconfirmed': 'Usmjerivač je prihvatio zahtjev, ali nije se moglo potvrditi da mapiranje radi. Neki usmjerivači tiho prihvate zahtjev, a ne primijene ga. Pokušaj provjeru povezivosti izvan mreže.',
  'settings.torrents.portMapFailed': 'Port nije bilo moguće mapirati: {error}',
  'settings.torrents.portMapUnavailable': 'Ova verzija još ne nudi mapiranje porta.',
  'settings.torrents.networkTitle': 'Otkrivanje peerova',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Pronalazi peerove bez ikakvog trackera, koristeći druge BitTorrent klijente kao distribuirani imenik.',
  'settings.torrents.pex': 'Razmjena peerova (PEX)',
  'settings.torrents.pexHint': 'Razmjenjuje poznate peerove s već povezanima, kako bi se roj s malo peerova brže pronašao.',
  'settings.torrents.privateNote': 'Privatni torrent automatski isključuje oboje čim su mu poznati metapodaci, bez obzira na to što je ovdje postavljeno: odmah kod prenesene .torrent datoteke ili čim vlastiti metapodaci magnet poveznice stignu iz roja. Većina privatnih trackera blokira račune koji koriste bilo što od toga.',
  'container.noJD': 'šifrirana je i može je otvoriti samo pozadina JDownloader. Nijedna nije postavljena: postavi KL_JD na JDownloader do kojeg ova instanca dopire i ponovno je pokreni.',
  'container.jdOff': 'šifrirana je i može je otvoriti samo pozadina JDownloader. „Pozadina JDownloader” isključena je na stranici Moduli.',
  'torrent.staging': 'Dodavanje…',
