  'settings.torrents.notApplied': 'Ovaj build još ne primjenjuje dvije od postavki ispod. Ograničenje slanja sprema se i provjerava, ali ga mehanizam ne može primijeniti na preuzimanje koje je u tijeku. Ni DHT ni PEX ne dopiru do običnog torrenta: on seeda s oba uključena, što god ovdje bilo postavljeno. Privatni torrent radi drukčije, kako objašnjava (i) kod „Otkrivanje peerova”.',
  'onboarding.step': 'Korak {n} od {total}',
  'onboarding.skip': 'Preskoči',
  'onboarding.back': 'Natrag',
  'onboarding.next': 'Dalje',
  'onboarding.finish': 'Gotovo',
  'onboarding.welcome.title': 'Dobro došao u KnightLoader',
  'onboarding.welcome.body': 'KnightLoader je upravitelj preuzimanja koji sam hostiraš. Zalijepi ili ispusti poveznicu i odgovarajuća pozadina je dohvaća: ugrađeni mehanizam za obične poveznice na datoteke, yt-dlp za medijske stranice, debrid usluga za hostere koje već plaćaš ili headless JDownloader za sve ostalo. Ova kratka tura pokazuje jedinu postavku koju vrijedi provjeriti prije početka.',
  'onboarding.welcome.langLabel': 'Jezik sučelja',
  'onboarding.folder.title': 'Gdje bi datoteke trebale završiti?',
  'onboarding.folder.body': 'Ovo je mapa u koju se zapisuju gotova preuzimanja. Upiši putanju ili je potraži na poslužitelju. Možeš je bilo kad ponovno promijeniti na stranici postavki Općenito.',
  'onboarding.accounts.title': 'Premium hosteri, kad god ih poželiš',
  'onboarding.accounts.body': 'Red čekanja radi i bez ikakvog računa. Kad poželiš punu brzinu kod hostera ili debrid usluge koju već plaćaš, dodaj njezinu prijavu pod Računi. Ništa od toga ne moraš sada postavljati.',
  'onboarding.accounts.link': 'Otvori Račune',
  'onboarding.finished.title': 'Spreman si',
  'onboarding.finished.body': 'Time turneja završava. Stranica Pomoć unutar Postavki sadrži potpuni pregled svega ostalog što ova verzija radi, a većina kontrola nosi vlastito objašnjenje iza ikone (i).',

