  'settings.nav.shortcuts': 'Prečaci',
  'settings.shortcuts.subtitle': 'Sve naredbe koje dolaze sa zadanim prečacem tipkovnice, grupirane prema mjestu primjene. Promijeni pridruživanje, ili ga vrati na zadano.',
  'settings.shortcuts.empty': 'Nijedna naredba još nema zadani prečac.',
  'settings.shortcuts.change': 'Promijeni',
  'settings.shortcuts.reset': 'Vrati',
  'settings.shortcuts.resetAll': 'Vrati sve na zadano',
  'settings.shortcuts.resetAllConfirmTitle': 'Vratiti sve prečace?',
  'settings.shortcuts.resetAllConfirmBody': 'Svaki ponovno dodijeljen prečac vraća se na zadanu vrijednost. Ovo se ne može poništiti.',
  'settings.shortcuts.resetAllConfirm': 'Vrati sve',
