  'settings.feeds.lastPolledHint': 'Kad je ova pretplata zadnji put pogledana, bez obzira na to je li taj pogled uspio. Zaboravlja se kad se poslužitelj ponovno pokrene, a ono što je pretplata već dodala ne zaboravlja se, pa feed koji pratiš već mjesecima nekoliko sekundi nakon ponovnog pokretanja stoji kao neprovjeren.',
