  'settings.feeds.seededHint': 'Prva provjera nove pretplate zapisuje sve što feed u tom trenutku nosi i ne dodaje ništa od toga, da ti ne upadne cijeli arhiv izdavača odjednom. Dodaje se tek ono što se pojavi poslije.',
  'settings.feeds.remembered': 'Zapamćeno unosa: {n}',
  'settings.feeds.rememberedHint': 'Koliko unosa ova pretplata prepoznaje kad ih opet vidi, da se ne dodaju drugi put dok ih feed još isporučuje. Najviše 500 po pretplati. Najstariji ispadaju prvi, a unos koji je još u feedu nikad nije među njima.',
  'settings.feeds.test': 'Testiraj',
  'settings.feeds.testBusy': 'Dohvaćam…',
  'settings.feeds.testHint': 'Jednom dohvaća ovu adresu i pokazuje ti što je u njoj, da vidiš naslove prema kojima se provjerava tvoj filtar. Samo čita: ništa ne ulazi u sakupljač i ništa se ne zapisuje kao viđeno, pa ovo smiješ pritisnuti i na adresi koju još nisi spremio.',
