  'settings.headerProfiles.title': 'Profili zaglavlja',
  'settings.headerProfiles.hint': 'Neke stranice datoteku daju samo pregledniku koji je prijavljen ili koji dolazi s jedne od njihovih vlastitih stranica. Profil sprema zaglavlja za točno jednu stranicu, šifrirana isto kao i ključevi tvojih računa, a KnightLoader ih šalje uz svako preuzimanje s te stranice.',
  'settings.headerProfiles.empty': 'Još nema profila zaglavlja.',
  'settings.headerProfiles.emptyHint': 'Isplati se čim neko preuzimanje radi samo dok si prijavljen u pregledniku.',
  'settings.headerProfiles.add': 'Dodaj profil',
