  'settings.headerProfiles.nameHint': 'Naziv pod kojim se ovaj profil poziva, u Packagizer pravilu jednako kao i ovdje. Samo slova, znamenke i - _ ili .',
  'settings.headerProfiles.namePlaceholder': 'npr. forum',
  'settings.headerProfiles.origin': 'Stranica',
  'settings.headerProfiles.originHint': 'Zalijepi adresu stranice s koje si kopirao zaglavlja. Drugi port i http umjesto https vrijede kao druga stranica i trebaju vlastiti profil. Poddomena nije pokrivena profilom glavne domene.',
  'settings.headerProfiles.headers': 'Zaglavlja',
  'settings.headerProfiles.headerName': 'Naziv',
  'settings.headerProfiles.headerValue': 'Vrijednost',
  'settings.headerProfiles.valueStored': 'Spremljeno',
  'settings.headerProfiles.valueStoredHint': 'Vrijednost ostaje na ovoj instanci i nikad se ne šalje natrag na ovu stranicu. Ostavi polje kakvo jest da je zadržiš, ili upiši novu vrijednost da je zamijeniš.',
  'settings.headerProfiles.error.originInvalid': 'To nije http ni https adresa. Zalijepi adresu stranice, na primjer https://forum.example.org.',
  'settings.headerProfiles.error.originTaken': 'Profil „{profile}” već pokriva ovu stranicu. Uredi ga ili ga najprije obriši.',
  'settings.headerProfiles.error.nameNeeded': 'Ovu stranicu još ne pokriva nijedan profil, pa ovome daj naziv.',
  'settings.headerProfiles.error.nameInvalid': 'Naziv profila sadrži samo slova, znamenke i - _ ili ., najviše 64 znaka.',
