  'settings.rules.action.category': 'Kategorija',
  'settings.rules.action.categoryHint': 'Razvrstava podudarne poveznice u jednu od ladica s popisa Kategorije niže na ovoj stranici, a ladica sa sobom donosi vlastitu mapu, mjesto u redu, prekidač za raspakiravanje i pravilo za datoteku koja već postoji. Ostaviš li nepromijenjeno, nijedno pravilo o tome ništa ne govori i poveznica ostaje nerazvrstana. Navede li ovo pravilo uz to i mapu za preuzimanja, ta mapa pobjeđuje, a ladica i dalje daje sve ostalo. Navesti ladicu koja je obrisana odbija se pri spremanju, jer pravilo koje pokazuje na ladicu koje nema ne radi baš ništa ni na jednoj poveznici koju uhvati, i to bez ijedne riječi.',
  'settings.rules.action.categoryNone': 'Još nema kategorija. Prvo je stvori pod Kategorijama niže na ovoj stranici, inače bi ovo pravilo razvrstavalo poveznice u ladicu koje nema.',
