  'detail.onDiskHint': 'Koliko datoteka u ovoj sekundi mjeri na disku, pitano poslužitelja, a ne brojeno ovdje. Preuzimanje koje teče raste između dva pogleda, i ovo nije veličina koju je hoster najavio.',
  'detail.mirrorOf': 'Rezervna kopija od',
  'detail.times': 'Vremenske oznake',
  'detail.timesHint': 'Kad je ova poveznica stigla, kad se zadnji put promijenila i kad je završila. Vremena početka prijenosa nema: aplikacija ga nikad nije zabilježila, a vrijednost pogođena iz ostala tri bila bi broj po kojem ljudi postupaju.',
  'detail.nextTry': 'Sljedeći pokušaj',
  'detail.stalledSince': 'Stoji od',
  'detail.retries': 'Dosadašnja ponavljanja',
  'detail.retriesHint': 'Koliko je puta ovo preuzimanje ponovno pokušano nakon greške. Čim preuzimanje završi, brojač se vraća na nulu, pa gotov redak pokazuje nulu i onda kad su bila četiri pokušaja. Koliko je pokušaja preostalo ovdje ne piše: gornja granica ovisi o uzroku i o hosteru, a ova je stranica ne može izračunati.',
  'detail.stallRestarts': 'Ponovna pokretanja nakon zastoja',
  'detail.stallRestartsHint': 'Koliko je puta nadzor zastoja sam ponovno pokrenuo ovo preuzimanje. Vraća se na nulu čim preuzimanje završi, jednako kao brojač iznad.',
  'detail.failure': 'Što je pošlo po zlu',
