  'detail.message': 'Što je pozadina rekla',
  'detail.messageHint': 'Rečenica onoga što je ovo pokušalo dohvatiti, od riječi do riječi i neprevedena. To je trenutna greška i ništa drugo: ponovno pokretanje je briše, a ranije se nigdje ne čuvaju.',
  'detail.heldBack': 'Zadržava ga',
  'detail.doing': 'Trenutno radi',
  'detail.filtered': 'Zadržao filtar poveznica',
  'detail.gaveUp': 'Nema više pokušaja',
  'detail.gaveUpHint': 'Ovdje je namjerno kraj, a ne zato što su pokušaji potrošeni: captcha, pun disk ili pravilo koje za ovog hostera kaže „nikad”. Podizanje broja ponavljanja ovdje ne mijenja ništa. Sama oznaka ne zapisuje se u bazu, pa je nakon ponovnog pokretanja nema, iako razlog za nju ostaje.',
  'detail.rules': 'Pravila koja su ovo oblikovala',
  'detail.rulesHint': 'Pravila koja su se okinula na ovoj poveznici dok se pripremala, redoslijedom kojim su išla. Čuvaju se po nazivu, pa se pravilo koje je otad preimenovano više ne nalazi, a pravilo koje nikad nije imalo naziv čuva se po mjestu koje je tada imalo. Klik na jedno otvara ga u uređivaču pravila.',
  'detail.openRule': 'Otvori u uređivaču pravila',
  'detail.noRules': 'Nijedno pravilo nije diralo ovu poveznicu.',
  'detail.player': 'Reprodukcija',
  'detail.play': 'Reproduciraj ovdje',
  'detail.playHint': 'Reproducira datoteku ravno s ove instance, bez drugog preuzimanja. Dok ne pritisneš reprodukciju, ništa se ne dohvaća, a datoteka ostaje ondje gdje jest.',
  'detail.playPartial': 'Ovo preuzimanje nije gotovo. Reproducirati se može samo dio koji već leži na disku, preskakanje dalje od njega ne radi, a neke datoteke ne sviraju baš ništa dok posljednji bajt nije tu.',
