  'notifications.title': 'Obavijesti',
  'notifications.titleHint': 'Odluči za svaki događaj hoće li se prikazati kao obavijest u samoj aplikaciji, kao obavijest tvog operativnog sustava ili nikako. Obavijest sustava stiže do tebe samo dok je otvorena neka kartica KnightLoadera, a tihi način ispod vrijedi i povrh toga.',
  'notifications.channel.app': 'U aplikaciji',
