  'notifications.event.downloadDoneHint': 'Svako preuzimanje koje dođe do kraja to i javi. Dvjesto datoteka u redu znači dvjesto ovakvih poruka, pa dobro promisli prije nego ih pošalješ sustavu.',
  'notifications.event.downloadFailed': 'Preuzimanje nije uspjelo',
  'notifications.event.downloadFailedHint': 'Preuzimanje koje je odustalo. Tihi način ovu obavijest nikad ne skriva.',
  'notifications.event.extractionDone': 'Raspakiravanje gotovo',
  'notifications.event.extractionDoneHint': 'Arhiva koja je gotova s raspakiravanjem. To se dosad nigdje nije javljalo, pa u početku stoji na „Ne prikazuj ništa”.',
  'notifications.event.extractionFailed': 'Raspakiravanje nije uspjelo',
  'notifications.event.extractionFailedHint': 'Arhiva koja je stala prije kraja. Najčešće nedostaje lozinka, a datoteke ostaju ležati dok se time ne pozabaviš.',
  'notifications.event.captchaWaiting': 'Captcha čeka',
  'notifications.event.captchaWaitingHint': 'Prozor s captchom u ovoj se kartici otvara ovako ili onako. U početku stoji na „Ne prikazuj ništa”, jer taj je prozor već sam poruka dok u njega gledaš. Postavi ga na obavijest sustava i captcha te u pozadinskoj kartici stigne prije nego što hoster odbaci sesiju.',
  'notifications.event.captchaFailed': 'Captcha nije uspjela',
  'notifications.event.captchaFailedHint': 'Nitko nije odgovorio na vrijeme ili odgovor nije prošao. Preuzimanje iza toga ostaje ležati.',
  'notifications.event.captchaResolved': 'Captcha riješena drugdje',
