  'notifications.systemUnavailable': 'Obavijesti sustava ovdje nisu dostupne: preglednik ih nudi samo preko HTTPS-a ili na localhostu. Sve na ovoj kartici svejedno se prikazuje u aplikaciji.',
  'notifications.systemBlocked': 'Preglednik blokira obavijesti za ovu adresu. Retci postavljeni na „Obavijest sustava” prikazuju se umjesto toga u aplikaciji, dok ih u postavkama za ovu stranicu u svom pregledniku opet ne dopustiš.',
  'notifications.systemNotGranted': 'Preglednik nije dao dopuštenje, pa ovaj događaj ostaje u aplikaciji. Odaberi „Obavijest sustava” još jednom da se pita ponovno.',
