  'disk.title': 'Odredišne mape',
  'disk.hint': 'Slobodan i zauzet prostor u svakoj mapi u koju preuzimanje može stići te koliko red čekanja još mora zapisati u svaku. Brojke dolaze iz istog upita prema kojem se provjeravaju ograničenja diska i stare su najviše nekoliko sekundi. Slobodno i zauzeto ne daju uvijek zajedno veličinu volumena: datotečni sustav zadržava dio za sustav, a kvota po korisniku može ovoj instanci ostaviti manje nego što volumen zapravo ima. Dvije mape na istom disku svaka prikazuju taj isti disk, pa retke nikad ne zbrajaj.',
  'disk.free': 'Slobodno',
  'disk.used': 'Zauzeto',
  'disk.size': 'Veličina diska',
  'disk.queued': 'Još za zapisati',
  'disk.queuedHint': 'Što bi preuzimanja koja su još otvorena dopisala u ovu mapu: veličina koju je hoster naveo, minus ono što je već stiglo. Preuzimanje čiju veličinu hoster ne kaže ovdje se broji kao ništa, pa je ovo donja granica, a nikad obećanje, i zato uz cijeli niz preuzimanja može stajati nula bajtova. Isključena preuzimanja ostaju vani, po istom pravilu po kojem rade brojači ispod popisa. Preuzimanje koje već teče najčešće je svoj prostor na disku dobilo rezerviran čim je krenulo, pa njegovi bajtovi već nedostaju u slobodnom prostoru pokraj ovoga i ne dolaze još povrh njega.',
  'disk.tasks': 'Preuzimanja: {n}',
  'disk.unknown': 'Ovaj sustav ne javlja slobodan prostor',
  'disk.unknownHint': 'Ne može se svaka jezgra pitati koliko je prostora ostalo na volumenu, a ovaj build nema poziv za onu na kojoj radi. Gdje odgovor nedostaje, ništa se ne zadržava: preuzimanja kreću kao da nije postavljeno nikakvo ograničenje diska. Ovaj redak stoji tu da to možeš razlikovati od diska koji je doista pun.',
  'disk.missing': 'Još nije napravljena',
  'disk.missingHint': 'Ovu mapu stvara onaj tko u nju zapiše prvu datoteku, pa je još nema. Brojke opisuju {path}, najbližu postojeću mapu iznad nje, a ona leži na disku na koji bi preuzimanje sletjelo.',
  'disk.measured': 'Izmjereno na {path}',
  'disk.elsewhereHint': 'Sama se mapa nije dala izmjeriti, pa je izmjerena najbliža iznad nje koja se dala. Ako se neki mount nije podigao, to može biti posve drugi disk od onoga kojemu je preuzimanje namijenjeno. Pogledaj putanju prije nego iz brojki išta zaključiš.',
  'disk.sampled': 'Očitano prije {n} s',
  'disk.tight': 'Red ne stane',
  'disk.tightHint': 'Ovoj se mapi duguje više nego što je na disku slobodno. Ovaj redak sam po sebi ne zaustavlja ništa: zadržava se pojedinačno, čim preuzimanje dođe na red, prema brojevima na stranici postavki Preuzimanja, a preuzimanje čiju veličinu nitko ne zna ovdje se uopće ne broji.',
  'disk.truncated': 'Nisu navedene sve mape',
  'disk.truncatedHint': 'Red cilja na više mapa izvan onih postavljenih nego što se isplati mjeriti pri svakom očitanju, pa su izostavljene one kojima se duguje najmanje. Svaka mapa koju si postavio uvijek je ovdje.',
  'disk.markLow': 'Ispod ovoga ne kreće ništa novo',
  'disk.markStop': 'Ispod ovoga sve staje',
  'disk.limits': 'Postavi granice diska',
  'disk.stripLabel': 'Prostor u odredišnim mapama',
  'disk.role.downloads': 'Mapa za preuzimanja',
  'disk.role.category': 'Mapa kategorije',
  'disk.role.work': 'Radna mapa',
  'disk.role.task': 'Postavljeno na samom preuzimanju',

  'settings.volume.title': 'Ograničenje volumena',
  'settings.volume.titleHint': 'Što je ova instanca preuzela do kraja, brojeno prema ograničenju koje sam zadaš, po razdoblju. Broji se veličina koju je hoster naveo za svako gotovo preuzimanje, pa se ono što završi bez navedene veličine broji kao nula, a ono što torrent pošalje ne broji se uopće. Ovo je očitanje tvojih preuzimanja, a ne mjerenje tvoje linije: bajtove koje je tvoj usmjerivač stvarno prenio ovdje ne vidi nitko.',
  'settings.volume.cap': 'Ograničenje po razdoblju (GB)',
  'settings.volume.capHint': '0 znači bez ograničenja: brojač i dalje radi, a ne zadržava se nikad ništa. Gigabajti su ovdje decimalni, onako kako davatelj usluge navodi tvoj paket, pa je 500 GB 500 000 000 000 bajtova, a ne 465 GiB. Vrijednosti za disk više gore na ovoj stranici binarni su GiB, druga jedinica za drugo pitanje.',
  'settings.volume.resetDay': 'Brojač kreće iznova na dan',
  'settings.volume.resetDayHint': 'Dan u mjesecu na koji se brojač vraća na nulu, obično dan kad ti se paket obnavlja. U mjesecu kraćem od dana koji si odabrao kreće iznova zadnjeg dana tog mjeseca i nikad ne sklizne u idući. Računa se po satu poslužitelja, a ne po satu tvog preglednika, jer red zadržava poslužitelj.',
  'settings.volume.action': 'Kad se ograničenje dosegne',
  'settings.volume.actionHint': 'Prijenos koji već teče nikad se ne prekida, koji god odgovor odabrao: zaustavljanje usred datoteke baca bajtove koje si već potrošio. „Samo mi javi” ne mijenja ništa i brojač ostaje cijela značajka. „Ne pokreći više preuzimanja” pušta da završi ono što teče i zadržava red dok se brojač ne resetira, a svaki redak koji čeka to i kaže. „Uspori sve” pušta red da teče brzinom navedenom ispod.',
  'settings.volume.actionReport': 'Samo mi javi',
  'settings.volume.actionPause': 'Ne pokreći više preuzimanja',
  'settings.volume.actionThrottle': 'Uspori sve',
  'settings.volume.throttle': 'Brzina nakon ograničenja (KiB/s)',
  'settings.volume.throttleHint': 'Brzina koja vrijedi do kraja razdoblja. Ona je gornja granica uz tvoja ostala ograničenja, a nikad umjesto njih: noćni prozor ili tihi prekidač koji traže manje i dalje pobjeđuju. 0 bi ovdje značila nikakvu granicu, a to je isto kao da nema ograničenja, pa je najmanji smislen broj 1.',
  'settings.volume.noCap': 'Bez ograničenja',
  'settings.volume.used': 'Preuzeto u ovom razdoblju',
  'settings.volume.usedOf': '{used} od {cap}',
  'settings.volume.resetsOn': 'Kreće iznova {date}',
  'settings.volume.reached': 'Ograničenje je dosegnuto.',

  'volume.title': 'Preuzeti volumen',
  'volume.titleHint': 'Gotova preuzimanja zbrojena po danu i po mjesecu, iz povijesti preuzimanja. Povijest ima vlastitu gornju granicu i može se ručno isprazniti, pa mjeseci koji su ispali sa začelja ovdje jednostavno nisu. Preuzimanje koje si ponovno pokrenuo broji se jednom, na dan kad je zadnji put završilo. Kalendar je poslužiteljev, u zoni {zone}.',
  'volume.range.days': '30 dana',
  'volume.range.months': '12 mjeseci',
  'volume.split.total': 'Sve',
  'volume.split.host': 'Po hosteru',
  'volume.split.backend': 'Po pozadini',
  'volume.other': 'Sve ostalo',
  'volume.empty': 'U ovom razdoblju još ništa nije završilo.',
  'volume.unsizedHint': 'Kod {n} ovih preuzimanja hoster nikad nije naveo veličinu. Ona zbroju ne dodaju ništa, pa je stvarna brojka viša od nacrtane.',
  'volume.trimmedHint': 'Povijest je na svojoj granici, pa sve starije od njezina najstarijeg unosa nedostaje i u ovoj krivulji. Podigni gornju granicu povijesti na ovoj stranici ako želiš gledati dalje unatrag.',
  'volume.meter': 'Volumen',
  'volume.meterHint': 'Što je preuzeto do kraja otkako se brojač zadnji put resetirao, mjereno prema ograničenju na stranici postavki Preuzimanja. Broj se mijenja kad preuzimanje završi, a ne dok traje. Zbraja se iz povijesti preuzimanja, pa pražnjenje te povijesti vraća i ovaj brojač na nulu.',

