  'task.retry.skipDetail': 'Pokreće poveznicu odmah, umjesto na kraju čekanja. Brojač ide dalje: ovo je pokušaj koji je ionako bio na rasporedu, a ne dodatni.',
  'task.retry.skipFailed': 'Pokušaj se nije mogao pokrenuti.',
  'volume.rangeLabel': 'Razdoblje',
