  'settings.module.metrics': 'Adresa s mjernim vrijednostima za nadzorni sustav',
  'settings.health.title': 'Stanje upravo sada',
  'settings.health.titleHint': 'Ova stranica samo čita. Ništa na njoj ne pokreće, ne zaustavlja i ne mijenja ništa, a ni ako je ostaviš otvorenom, time se ništa ne mijenja. Vrijednosti se dohvaćaju svakih deset sekundi. Ne uspije li dohvat, ostaje stajati posljednje očitanje, umjesto da stranica ostane prazna. Dijelovi koje treba ispitati dijele se pola minute. Ono što ovdje piše može dakle biti do trideset sekundi iza redaka na stranici Preuzimanja.',
  'settings.health.version': 'Verzija',
