  'settings.health.uptimeHint': 'Koliko dugo radi ovaj proces, a ne koliko dugo radi računalo. Spremnik koji se prije sat vremena ponovno pokrenuo ovdje opet kreće od nule, što god domaćin govorio. Datum pokraj njega sat je poslužitelja, a ne sat tvog preglednika.',
  'settings.health.startedAt': 'Pokrenuto',
