  'health.remedy.store.failed': 'Baza podataka nije odgovorila. Preuzimanja teku dalje, ali se o njima više ništa ne zapisuje. Ponovno pokretanje bi dakle izgubilo sve što se otad promijenilo. Provjeri je li mapa s podacima još montirana i još upisiva.',
  'health.remedy.jd.unreachable': 'KL_JD imenuje adresu koju ova instanca trenutno ne doseže. Provjeri radi li spremnik s JDownloaderom i odgovara li njegov API port odavde. Poveznice koje može dohvatiti samo JDownloader dotad ostaju u redu i nisu propale.',
  'health.remedy.jd.notWired': 'JDownloader opet odgovara, ali je ovaj proces svoje pozadine povezao pri pokretanju i tada ga nije imao. Ponovno pokreni KnightLoader da ga uključi.',
  'health.remedy.ytdlp.missing': 'Pri pokretanju nije pronađen nijedan yt-dlp (KL_YTDLP ili „yt-dlp” u PATH-u). Medijske stranice tada propadnu s greškom same stranice, umjesto da se razlože na varijante. Da bi bio pronađen, treba ponovno pokretanje.',
  'health.remedy.disk.low': 'Odredišna mapa je ispod granice koju si postavio na stranici Preuzimanja. Ondje ne kreće ništa novo dok opet ne bude mjesta ili dok granicu ne spustiš. Ono što već radi ta granica ne zaustavlja.',
  'health.remedy.disk.elsewhere': 'Mape nema, pa brojke opisuju najbližu mapu iznad nje. Ako se montiranje nije podiglo, to je posve drugi disk. Pogledaj putanju prije nego što brojkama povjeruješ.',
  'health.remedy.accounts.benched': 'Barem jedan račun kod hostera nakon greške ostavlja se na miru. Sam se pokušava još jednom kad čekanje prođe, a čekanje se svaki put udvostručuje. Otvori Račune i pritisni Osvježi na tom retku ako želiš znati sada.',
  'health.remedy.accounts.invalid': 'Barem jedan račun kod hostera je odbijen. Pomaže novi ključ ili produljena pretplata, čekanje ne.',
  'health.remedy.feeds.failing': 'Kod barem jedne pretplate posljednji dohvat nije uspio. Koja i zašto, piše na stranici Preuzimanja pokraj feeda i u redovima dnevnika na stranici Dijagnostika.',
  'health.remedy.relay.down': 'Adresa releja je spremljena, a veza ne stoji. Ova instanca sama pokušava dalje, i lokalno sve radi kao inače. Samo izvana trenutno nije dostupna.',
  'health.remedy.captcha.waiting': 'Pozadina je stala i pita čovjeka. Iza toga se ništa ne miče dok netko ne odgovori.',
  'settings.health.tasks': 'Preuzimanja upravo sada',
