  'settings.health.nothingFailed': 'U popisu ništa nije propalo.',
  'settings.health.scrapeHint': 'Otvara drugu adresu koja iste vrijednosti ispisuje kao čisti tekst, u formatu koji čitaju Prometheus i alati građeni po njemu. Nju se dohvaća, nikad se ne šalje: s ovog računala ne odlazi ništa dok tvoj vlastiti nadzor ne dođe ovamo i ne zatraži ih. Dok je ovo isključeno, te adrese uopće nema i ona odgovara s 404, jednako kao svaka druga adresa koju ova aplikacija nema. Na instanci s lozinkom dohvat treba jedan od tvojih API tokena, a to se može objasniti svakom sakupljaču. Sakupljač ne šalje podatak o podrijetlu i zato prolazi; kartica preglednika na drugoj adresi ga šalje i biva odbijena kad ne odgovara vlastitoj adresi ove instance. U tekstu stoje putanje tvojih odredišnih mapa, pa ga daj samo onamo kamo bi dao i same nazive mapa.',
  'settings.health.scrapeUrl': 'Adresa s mjernim vrijednostima',
