  'settings.owner.envHow': 'Želiš li raditi pod drugim računom, imenuj ga u naredbi za pokretanje: --user <uid>:<gid>. Na Unraidu to ide u Extra Parameters, a spremnik treba iznova stvoriti da bi to stupilo na snagu.',
  'settings.owner.desktopNote': 'Desktop aplikacija radi pod tvojim vlastitim računom. PUID, PGID i UMASK postavke su spremnika i ovdje ne rade ništa.',
