  'settings.owner.v.ownerMismatch': 'Datoteke ovdje slijeću kao {fileOwner}, a mapa pripada {dirOwner}. Čitanje uglavnom još ide, preimenovanje, premještanje i brisanje s drugog računa ne, a sve što očekuje da mapa posjeduje vlastiti sadržaj drži te datoteke tuđima.',
  'settings.owner.v.groupUnreadable': 'Datoteke ovdje slijeću s pravima {fileMode}, pa ih može otvoriti samo {fileOwner}. Sve što radi pod drugim računom vidi nazive i ništa više.',
