  'settings.selftest.ytdlp.oldAdvice': 'U spremniku yt-dlp dolazi iz Alpine paketa koji je bio aktualan kad je slika građena, i nikad se sam ne ažurira. Dohvati noviju sliku, ili u spremnik montiraj vlastiti yt-dlp i usmjeri KL_YTDLP na njega.',
  'settings.selftest.ytdlp.missing': 'Nije pronađen, pa medijske stranice umjesto toga propadaju s vlastitom greškom hostera.',
  'settings.selftest.ytdlp.missingAdvice': 'Usmjeri KL_YTDLP na izvršnu datoteku, ili stavi yt-dlp u PATH. Traži se jednom pri pokretanju, pa se onaj koji sada instaliraš koristi tek nakon ponovnog pokretanja.',
  'settings.selftest.ytdlp.undated': '{version} ne izgleda kao datum, pa se starost ne da procijeniti.',
  'settings.selftest.folders': 'Mapa za preuzimanja i radna mapa',
  'settings.selftest.folders.allOk': 'Svaka provjerena mapa postoji i u nju se da pisati.',
  'settings.selftest.folders.someBad': 'Kod barem jedne mape ima nešto što vrijedi pogledati.',
  'settings.selftest.folders.none': 'Nijedna se mapa uopće nije dala izmjeriti.',
  'settings.selftest.folders.ok': 'U {dir} se da pisati, slobodno {free}.',
  'settings.selftest.folders.notWritable': 'U {dir} se ne da pisati.',
  'settings.selftest.folders.notWritableAdvice': 'Ovaj proces radi kao uid {uid}. Pogledaj kome ta mapa pripada na domaćinu i smije li taj uid u njoj pisati.',
  'settings.selftest.folders.missing': '{dir} još nema, pa brojke umjesto toga opisuju {measured}.',
  'settings.selftest.folders.missingAdvice': 'To je normalno za mapu u koju još ništa nije zapisano, stvara je prvo preuzimanje. Ako je {measured} korijen diska, nedostaje montiranje koje si očekivao, i preuzimanje slijeće u spremnik umjesto na tvoj disk.',
  'settings.selftest.folders.low': 'Na {dir} je ostalo samo {free}, ispod granice od {mark} na kojoj se red zaustavlja.',
  'settings.selftest.folders.noMark': 'Na {dir} je slobodno {free}. Nisi postavio čvrstu granicu, pa red zadržava preuzimanje samo kad ono ionako ne bi stalo.',
  'settings.selftest.folders.unknown': 'Ovu platformu nije moguće pitati koliko je mjesta na {dir}.',
  'settings.selftest.accounts': 'Debrid prijave',
  'settings.selftest.accounts.none': 'Nije postavljen nijedan debrid račun, pa nije bilo što provjeriti.',
  'settings.selftest.accounts.allOk': 'Svih {n} prijava je prihvaćeno.',
  'settings.selftest.accounts.someFailed': 'Odbijeno je {bad} od {n} prijava.',
